btn_sol_lua_animado.js:
(function(){
  var btn = document.getElementById('sl-dark-toggle');
  if(!btn) return;
  var root = document.documentElement;
  var stored = localStorage.getItem('sl_theme');
  if(stored === 'dark') root.classList.add('dark');
  function toggle(){
    var isDark = root.classList.toggle('dark');
    localStorage.setItem('sl_theme', isDark ? 'dark' : 'light');
    root.setAttribute('data-bs-theme', isDark ? 'dark' : 'light');
  }
  btn.addEventListener('click', toggle);
  var mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
  if(!stored && mediaQuery.matches) root.classList.add('dark');
})();

btn_toggle_switch_pill.js:
(function(){
  var chk = document.getElementById('sl-theme-switch');
  if(!chk) return;
  var root = document.documentElement;
  var stored = localStorage.getItem('sl_theme');
  var sys = window.matchMedia('(prefers-color-scheme: dark)').matches;
  var isDark = stored ? stored === 'dark' : sys;
  if(isDark){ root.classList.add('dark'); root.setAttribute('data-bs-theme','dark'); chk.checked = true; }
  chk.addEventListener('change', function(){
    var on = this.checked;
    root.classList.toggle('dark', on);
    root.setAttribute('data-bs-theme', on ? 'dark' : 'light');
    localStorage.setItem('sl_theme', on ? 'dark' : 'light');
  });
})();
